CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS noctis;
REVOKE ALL ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON SCHEMA noctis FROM PUBLIC;
GRANT USAGE ON SCHEMA noctis TO noctis_api,noctis_auth,noctis_worker;
SET search_path=noctis,pg_catalog;

CREATE TABLE users(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,email text NOT NULL UNIQUE CHECK(email=lower(email)),password_hash text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE TABLE profiles(user_id text PRIMARY KEY REFERENCES users ON DELETE CASCADE,name varchar(60) NOT NULL,handle varchar(32) NOT NULL UNIQUE,avatar integer NOT NULL DEFAULT 12,avatar_upload_id text,bio varchar(600) NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'online' CHECK(status IN('online','idle','offline')),activity varchar(120) NOT NULL DEFAULT '',color varchar(7) NOT NULL DEFAULT '#aaa2ff',profile_visibility text NOT NULL DEFAULT 'community' CHECK(profile_visibility IN('community','friends','private')),allow_dm text NOT NULL DEFAULT 'friends' CHECK(allow_dm IN('community','friends','nobody')),allow_invites boolean NOT NULL DEFAULT true,show_activity boolean NOT NULL DEFAULT true,allow_friend_requests boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_settings(user_id text REFERENCES users ON DELETE CASCADE,key varchar(40),value text NOT NULL,PRIMARY KEY(user_id,key));
CREATE TABLE devices(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,user_id text NOT NULL REFERENCES users ON DELETE CASCADE,label varchar(120) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,user_id text NOT NULL REFERENCES users ON DELETE CASCADE,device_id text NOT NULL REFERENCES devices ON DELETE CASCADE,token_hash char(64) UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days',revoked_at timestamptz);
CREATE INDEX sessions_user_active ON sessions(user_id,expires_at) WHERE revoked_at IS NULL;
CREATE TABLE friendships(requester_id text REFERENCES users ON DELETE CASCADE,recipient_id text REFERENCES users ON DELETE CASCADE,status text NOT NULL CHECK(status IN('pending','accepted')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(requester_id,recipient_id),CHECK(requester_id<>recipient_id));
CREATE UNIQUE INDEX friendship_pair ON friendships(least(requester_id,recipient_id),greatest(requester_id,recipient_id));
CREATE TABLE user_blocks(blocker_id text REFERENCES users ON DELETE CASCADE,blocked_id text REFERENCES users ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(blocker_id,blocked_id),CHECK(blocker_id<>blocked_id));

CREATE TABLE servers(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,owner_id text NOT NULL REFERENCES users,name varchar(80) NOT NULL,description varchar(600) NOT NULL DEFAULT '',mark varchar(4) NOT NULL DEFAULT 'N',image text NOT NULL DEFAULT '/images/mountains.jpg',color varchar(7) NOT NULL DEFAULT '#aaa2ff',category varchar(40) NOT NULL DEFAULT 'Community',is_public boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX servers_discover ON servers(category,name) WHERE is_public AND deleted_at IS NULL;
CREATE TABLE server_members(server_id text REFERENCES servers ON DELETE CASCADE,user_id text REFERENCES users ON DELETE CASCADE,joined_at timestamptz NOT NULL DEFAULT now(),last_read_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(server_id,user_id));
CREATE INDEX server_members_user ON server_members(user_id,server_id);
CREATE TABLE roles(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,server_id text NOT NULL REFERENCES servers ON DELETE CASCADE,name varchar(40) NOT NULL,position integer NOT NULL CHECK(position BETWEEN 0 AND 100),color varchar(7) NOT NULL DEFAULT '#a2a3ae',is_default boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(server_id,name),UNIQUE(server_id,id));
CREATE UNIQUE INDEX roles_default ON roles(server_id) WHERE is_default;
CREATE TABLE permissions(code text PRIMARY KEY);
INSERT INTO permissions VALUES ('VIEW_CHANNEL'),('SEND_MESSAGES'),('MANAGE_MESSAGES'),('ATTACH_FILES'),('ADD_REACTIONS'),('CONNECT_VOICE'),('SPEAK'),('STREAM'),('MUTE_MEMBERS'),('DEAFEN_MEMBERS'),('MOVE_MEMBERS'),('CREATE_INVITE'),('MANAGE_CHANNELS'),('MANAGE_ROLES'),('MANAGE_MISSIONS'),('MANAGE_EVENTS'),('MANAGE_SERVER'),('KICK_MEMBERS'),('BAN_MEMBERS'),('VIEW_AUDIT_LOG');
CREATE TABLE role_permissions(role_id text REFERENCES roles ON DELETE CASCADE,permission text REFERENCES permissions ON DELETE CASCADE,PRIMARY KEY(role_id,permission));
CREATE TABLE member_roles(server_id text,user_id text,role_id text,PRIMARY KEY(server_id,user_id,role_id),FOREIGN KEY(server_id,user_id) REFERENCES server_members ON DELETE CASCADE,FOREIGN KEY(server_id,role_id) REFERENCES roles(server_id,id) ON DELETE CASCADE);
CREATE TABLE channel_categories(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,server_id text NOT NULL REFERENCES servers ON DELETE CASCADE,name varchar(60) NOT NULL,position integer NOT NULL DEFAULT 0,UNIQUE(server_id,id));
CREATE TABLE channels(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,server_id text NOT NULL REFERENCES servers ON DELETE CASCADE,category_id text,name varchar(60) NOT NULL,slug varchar(60) NOT NULL,description varchar(300) NOT NULL DEFAULT '',kind text NOT NULL DEFAULT 'text' CHECK(kind IN('text','voice')),is_private boolean NOT NULL DEFAULT false,position integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(server_id,slug),UNIQUE(server_id,id),FOREIGN KEY(server_id,category_id) REFERENCES channel_categories(server_id,id));
CREATE TABLE channel_role_permissions(channel_id text REFERENCES channels ON DELETE CASCADE,role_id text REFERENCES roles ON DELETE CASCADE,permission text REFERENCES permissions,allowed boolean NOT NULL,PRIMARY KEY(channel_id,role_id,permission));
CREATE TABLE direct_conversations(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,name varchar(80),created_by text NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE direct_conversation_members(conversation_id text REFERENCES direct_conversations ON DELETE CASCADE,user_id text REFERENCES users ON DELETE CASCADE,last_read_at timestamptz NOT NULL DEFAULT now(),joined_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(conversation_id,user_id));
CREATE INDEX direct_member_user ON direct_conversation_members(user_id,conversation_id);
CREATE TABLE messages(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,channel_id text REFERENCES channels ON DELETE CASCADE,conversation_id text REFERENCES direct_conversations ON DELETE CASCADE,author_id text NOT NULL REFERENCES users,body varchar(4000) NOT NULL DEFAULT '',client_nonce uuid NOT NULL DEFAULT gen_random_uuid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,CHECK(num_nonnulls(channel_id,conversation_id)=1),UNIQUE(author_id,client_nonce));
CREATE INDEX messages_channel_cursor ON messages(channel_id,created_at DESC,id) WHERE deleted_at IS NULL;
CREATE INDEX messages_conversation_cursor ON messages(conversation_id,created_at DESC,id) WHERE deleted_at IS NULL;
CREATE INDEX messages_search ON messages USING gin(to_tsvector('english',body)) WHERE deleted_at IS NULL;
CREATE TABLE message_replies(message_id text PRIMARY KEY REFERENCES messages ON DELETE CASCADE,parent_id text NOT NULL REFERENCES messages ON DELETE CASCADE,CHECK(message_id<>parent_id));
CREATE TABLE message_reactions(message_id text REFERENCES messages ON DELETE CASCADE,user_id text REFERENCES users ON DELETE CASCADE,emoji varchar(32),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(message_id,user_id,emoji));
CREATE TABLE message_mentions(message_id text REFERENCES messages ON DELETE CASCADE,user_id text REFERENCES users ON DELETE CASCADE,PRIMARY KEY(message_id,user_id));
CREATE TABLE uploads(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,owner_id text NOT NULL REFERENCES users,channel_id text REFERENCES channels ON DELETE CASCADE,conversation_id text REFERENCES direct_conversations ON DELETE CASCADE,purpose text NOT NULL CHECK(purpose IN('message','avatar')),storage_key uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(),original_name varchar(120) NOT NULL,content_type varchar(80) NOT NULL,byte_size integer NOT NULL CHECK(byte_size BETWEEN 1 AND 8388608),sha256 char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK((purpose='avatar' AND channel_id IS NULL AND conversation_id IS NULL) OR (purpose='message' AND num_nonnulls(channel_id,conversation_id)=1)));
ALTER TABLE profiles ADD CONSTRAINT avatar_upload FOREIGN KEY(avatar_upload_id) REFERENCES uploads ON DELETE SET NULL;
CREATE TABLE message_attachments(message_id text REFERENCES messages ON DELETE CASCADE,upload_id text REFERENCES uploads,PRIMARY KEY(message_id,upload_id));
CREATE TABLE pinned_messages(message_id text PRIMARY KEY REFERENCES messages ON DELETE CASCADE,pinned_by text NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE channel_reads(channel_id text REFERENCES channels ON DELETE CASCADE,user_id text REFERENCES users ON DELETE CASCADE,read_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(channel_id,user_id));
CREATE TABLE invitations(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,server_id text NOT NULL REFERENCES servers ON DELETE CASCADE,created_by text NOT NULL REFERENCES users,token_hash char(64) NOT NULL UNIQUE,max_uses integer NOT NULL CHECK(max_uses BETWEEN 1 AND 1000),uses integer NOT NULL DEFAULT 0 CHECK(uses>=0),expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE missions(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,server_id text NOT NULL REFERENCES servers ON DELETE CASCADE,created_by text NOT NULL REFERENCES users,title varchar(100) NOT NULL,description varchar(2000) NOT NULL,category varchar(40) NOT NULL DEFAULT 'Community',icon varchar(40) NOT NULL DEFAULT 'Target',color varchar(7) NOT NULL DEFAULT '#aaa2ff',due_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz);
CREATE INDEX missions_server ON missions(server_id,created_at);
CREATE TABLE mission_objectives(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,mission_id text NOT NULL REFERENCES missions ON DELETE CASCADE,description varchar(300) NOT NULL,position integer NOT NULL,verification text NOT NULL DEFAULT 'self' CHECK(verification IN('self','moderator')),UNIQUE(mission_id,position));
CREATE TABLE mission_members(mission_id text REFERENCES missions ON DELETE CASCADE,user_id text REFERENCES users ON DELETE CASCADE,joined_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(mission_id,user_id));
CREATE TABLE mission_progress(objective_id text REFERENCES mission_objectives ON DELETE CASCADE,user_id text REFERENCES users ON DELETE CASCADE,completed_at timestamptz NOT NULL DEFAULT now(),verified_by text NOT NULL REFERENCES users,PRIMARY KEY(objective_id,user_id));
CREATE TABLE badges(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,name varchar(60) NOT NULL,icon varchar(40) NOT NULL DEFAULT 'Award',server_id text REFERENCES servers ON DELETE CASCADE);
CREATE TABLE mission_rewards(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,mission_id text NOT NULL UNIQUE REFERENCES missions ON DELETE CASCADE,xp integer NOT NULL CHECK(xp BETWEEN 0 AND 10000),badge_id text REFERENCES badges);
CREATE TABLE xp_transactions(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,user_id text NOT NULL REFERENCES users ON DELETE CASCADE,server_id text NOT NULL REFERENCES servers ON DELETE CASCADE,reward_id text REFERENCES mission_rewards,amount integer NOT NULL CHECK(amount BETWEEN 0 AND 10000),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,reward_id));
CREATE INDEX xp_user_server ON xp_transactions(user_id,server_id);
CREATE TABLE user_badges(user_id text REFERENCES users ON DELETE CASCADE,badge_id text REFERENCES badges ON DELETE CASCADE,awarded_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,badge_id));
CREATE VIEW leaderboards WITH(security_invoker=true) AS SELECT server_id,user_id,sum(amount)::integer AS xp FROM xp_transactions GROUP BY server_id,user_id;
CREATE TABLE events(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,server_id text NOT NULL REFERENCES servers ON DELETE CASCADE,created_by text NOT NULL REFERENCES users,title varchar(100) NOT NULL,description varchar(2000) NOT NULL DEFAULT '',starts_at timestamptz NOT NULL,ends_at timestamptz,icon varchar(40) NOT NULL DEFAULT 'CalendarDays',created_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,CHECK(ends_at IS NULL OR ends_at>starts_at));
CREATE INDEX events_server_start ON events(server_id,starts_at) WHERE deleted_at IS NULL;
CREATE TABLE event_participants(event_id text REFERENCES events ON DELETE CASCADE,user_id text REFERENCES users ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(event_id,user_id));
CREATE TABLE notifications(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,user_id text NOT NULL REFERENCES users ON DELETE CASCADE,actor_id text REFERENCES users,server_id text REFERENCES servers ON DELETE CASCADE,kind varchar(40) NOT NULL,title varchar(160) NOT NULL,body varchar(300) NOT NULL DEFAULT '',route varchar(200) NOT NULL DEFAULT 'home',read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX notifications_user ON notifications(user_id,created_at DESC);

CREATE TABLE oauth_accounts(provider text,subject text,user_id text NOT NULL REFERENCES users ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(provider,subject),UNIQUE(provider,user_id));
CREATE TABLE oauth_states(id text PRIMARY KEY,state_hash char(64) NOT NULL UNIQUE,provider text NOT NULL,user_id text REFERENCES users ON DELETE CASCADE,session_id text REFERENCES sessions ON DELETE CASCADE,purpose text NOT NULL CHECK(purpose IN('login','integration')),verifier_encrypted text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE integrations(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,user_id text NOT NULL REFERENCES users ON DELETE CASCADE,provider text NOT NULL CHECK(provider IN('github','calendar','spotify','youtube','twitch')),status text NOT NULL DEFAULT 'connected' CHECK(status IN('connected','error','disconnected')),last_synced_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,provider));
CREATE TABLE integration_credentials(integration_id text PRIMARY KEY REFERENCES integrations ON DELETE CASCADE,access_encrypted text NOT NULL,refresh_encrypted text,expires_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE integration_items(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,integration_id text NOT NULL REFERENCES integrations ON DELETE CASCADE,external_id varchar(200) NOT NULL,title varchar(300) NOT NULL,url varchar(1000),occurred_at timestamptz NOT NULL DEFAULT now(),UNIQUE(integration_id,external_id));
CREATE TABLE webhooks(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,server_id text NOT NULL REFERENCES servers ON DELETE CASCADE,channel_id text NOT NULL REFERENCES channels ON DELETE CASCADE,created_by text NOT NULL REFERENCES users,name varchar(80) NOT NULL,secret_encrypted text NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_deliveries(webhook_id text REFERENCES webhooks ON DELETE CASCADE,delivery_id varchar(100),received_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(webhook_id,delivery_id));
CREATE TABLE jobs(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,kind text NOT NULL CHECK(kind IN('webhook','integration')),integration_id text REFERENCES integrations ON DELETE CASCADE,webhook_id text REFERENCES webhooks ON DELETE CASCADE,body varchar(4000),attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),run_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,completed_at timestamptz,failed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_ready ON jobs(run_at) WHERE completed_at IS NULL AND failed_at IS NULL;
CREATE TABLE moderation_actions(id text PRIMARY KEY DEFAULT gen_random_uuid()::text,server_id text NOT NULL REFERENCES servers ON DELETE CASCADE,actor_id text NOT NULL REFERENCES users,target_id text NOT NULL REFERENCES users,action text NOT NULL CHECK(action IN('kick','ban','unban','mute','deafen','move')),reason varchar(500) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE server_bans(server_id text REFERENCES servers ON DELETE CASCADE,user_id text REFERENCES users ON DELETE CASCADE,actor_id text NOT NULL REFERENCES users,reason varchar(500) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(server_id,user_id));
CREATE TABLE voice_participants(connection_id text PRIMARY KEY,user_id text NOT NULL REFERENCES users ON DELETE CASCADE,session_id text NOT NULL REFERENCES sessions ON DELETE CASCADE,channel_id text NOT NULL REFERENCES channels ON DELETE CASCADE,muted boolean NOT NULL DEFAULT true,deafened boolean NOT NULL DEFAULT false,camera boolean NOT NULL DEFAULT false,screen boolean NOT NULL DEFAULT false,server_muted boolean NOT NULL DEFAULT false,server_deafened boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,channel_id));
CREATE TABLE presence(session_id text PRIMARY KEY REFERENCES sessions ON DELETE CASCADE,user_id text NOT NULL REFERENCES users ON DELETE CASCADE,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits(bucket char(64) PRIMARY KEY,window_start timestamptz NOT NULL DEFAULT now(),hits integer NOT NULL DEFAULT 1);
CREATE TABLE audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id text,action varchar(80) NOT NULL,target varchar(160) NOT NULL,server_id text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT clock_timestamp(),previous_hash char(64) NOT NULL,record_hash char(64) NOT NULL);
CREATE INDEX audit_server_time ON audit_logs(server_id,created_at DESC);

CREATE FUNCTION current_user_id() RETURNS text LANGUAGE sql STABLE SET search_path=pg_catalog AS $$ SELECT nullif(current_setting('noctis.user_id',true),'') $$;
CREATE FUNCTION session_valid() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM noctis.sessions s JOIN noctis.users u ON u.id=s.user_id WHERE s.id=nullif(current_setting('noctis.session_id',true),'') AND s.user_id=noctis.current_user_id() AND s.revoked_at IS NULL AND s.expires_at>now() AND s.last_seen_at>now()-interval '7 days' AND u.deleted_at IS NULL) $$;
CREATE FUNCTION member(sid text,uid text DEFAULT noctis.current_user_id()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM noctis.server_members m JOIN noctis.servers s ON s.id=m.server_id WHERE m.server_id=sid AND m.user_id=uid AND s.deleted_at IS NULL AND NOT EXISTS(SELECT 1 FROM noctis.server_bans b WHERE b.server_id=sid AND b.user_id=uid)) $$;
CREATE FUNCTION has_permission(sid text,perm text,uid text DEFAULT noctis.current_user_id()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT noctis.member(sid,uid) AND (EXISTS(SELECT 1 FROM noctis.servers WHERE id=sid AND owner_id=uid) OR EXISTS(SELECT 1 FROM noctis.roles r JOIN noctis.role_permissions rp ON rp.role_id=r.id WHERE r.server_id=sid AND rp.permission=perm AND (r.is_default OR EXISTS(SELECT 1 FROM noctis.member_roles mr WHERE mr.role_id=r.id AND mr.user_id=uid AND mr.server_id=sid)))) $$;
CREATE FUNCTION channel_permission(cid text,perm text,uid text DEFAULT noctis.current_user_id()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT EXISTS(SELECT 1 FROM noctis.channels c JOIN noctis.servers s ON s.id=c.server_id WHERE c.id=cid AND c.deleted_at IS NULL AND noctis.member(c.server_id,uid) AND (s.owner_id=uid OR (
   (NOT c.is_private OR EXISTS(SELECT 1 FROM noctis.channel_role_permissions cp JOIN noctis.roles r ON r.id=cp.role_id WHERE cp.channel_id=cid AND cp.permission='VIEW_CHANNEL' AND cp.allowed AND r.server_id=c.server_id AND (r.is_default OR EXISTS(SELECT 1 FROM noctis.member_roles mr WHERE mr.role_id=r.id AND mr.user_id=uid))))
   AND NOT EXISTS(SELECT 1 FROM noctis.channel_role_permissions cp JOIN noctis.roles r ON r.id=cp.role_id WHERE cp.channel_id=cid AND cp.permission=perm AND NOT cp.allowed AND r.server_id=c.server_id AND (r.is_default OR EXISTS(SELECT 1 FROM noctis.member_roles mr WHERE mr.role_id=r.id AND mr.user_id=uid)))
   AND (noctis.has_permission(c.server_id,perm,uid) OR EXISTS(SELECT 1 FROM noctis.channel_role_permissions cp JOIN noctis.roles r ON r.id=cp.role_id WHERE cp.channel_id=cid AND cp.permission=perm AND cp.allowed AND r.server_id=c.server_id AND (r.is_default OR EXISTS(SELECT 1 FROM noctis.member_roles mr WHERE mr.role_id=r.id AND mr.user_id=uid))))))) $$;
CREATE FUNCTION blocked(a text,b text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM noctis.user_blocks WHERE (blocker_id=a AND blocked_id=b) OR (blocker_id=b AND blocked_id=a)) $$;
CREATE FUNCTION friends(a text,b text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT NOT noctis.blocked(a,b) AND EXISTS(SELECT 1 FROM noctis.friendships WHERE status='accepted' AND ((requester_id=a AND recipient_id=b) OR (requester_id=b AND recipient_id=a))) $$;
CREATE FUNCTION can_profile(uid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT uid=noctis.current_user_id() OR (NOT noctis.blocked(uid,noctis.current_user_id()) AND EXISTS(SELECT 1 FROM noctis.profiles p WHERE p.user_id=uid AND (p.profile_visibility<>'private' AND noctis.friends(uid,noctis.current_user_id()) OR p.profile_visibility='community' AND EXISTS(SELECT 1 FROM noctis.server_members a JOIN noctis.server_members b ON a.server_id=b.server_id WHERE a.user_id=uid AND b.user_id=noctis.current_user_id())))) $$;
CREATE FUNCTION in_conversation(cid text,uid text DEFAULT noctis.current_user_id()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM noctis.direct_conversation_members WHERE conversation_id=cid AND user_id=uid) AND NOT EXISTS(SELECT 1 FROM noctis.direct_conversation_members WHERE conversation_id=cid AND noctis.blocked(uid,user_id)) $$;
CREATE FUNCTION can_message(mid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM noctis.messages m WHERE m.id=mid AND (noctis.channel_permission(m.channel_id,'VIEW_CHANNEL') OR noctis.in_conversation(m.conversation_id))) $$;
CREATE FUNCTION can_upload(uid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT EXISTS(SELECT 1 FROM noctis.uploads u WHERE u.id=uid AND (u.owner_id=noctis.current_user_id() OR (u.purpose='avatar' AND EXISTS(SELECT 1 FROM noctis.profiles p WHERE p.avatar_upload_id=u.id AND noctis.can_profile(p.user_id))) OR EXISTS(SELECT 1 FROM noctis.message_attachments ma WHERE ma.upload_id=u.id AND noctis.can_message(ma.message_id)))) $$;
CREATE FUNCTION rank(sid text,uid text DEFAULT noctis.current_user_id()) RETURNS integer LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT CASE WHEN EXISTS(SELECT 1 FROM noctis.servers WHERE id=sid AND owner_id=uid) THEN 101 ELSE coalesce((SELECT max(r.position) FROM noctis.roles r WHERE r.server_id=sid AND (r.is_default OR EXISTS(SELECT 1 FROM noctis.member_roles mr WHERE mr.role_id=r.id AND mr.user_id=uid))),0) END $$;
CREATE FUNCTION append_audit(actor text,act text,tgt text,sid text,meta jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE prev text; stamp timestamptz:=clock_timestamp(); BEGIN
  IF length(meta::text)>2048 THEN RAISE EXCEPTION 'Audit metadata too large'; END IF;
  PERFORM pg_advisory_xact_lock(784135);
  SELECT record_hash INTO prev FROM noctis.audit_logs ORDER BY id DESC LIMIT 1;
  prev:=coalesce(prev,repeat('0',64));
  INSERT INTO noctis.audit_logs(actor_id,action,target,server_id,metadata,created_at,previous_hash,record_hash) VALUES(actor,act,tgt,sid,meta,stamp,prev,encode(public.digest(convert_to(jsonb_build_array(prev,actor,act,tgt,sid,meta,stamp)::text,'UTF8'),'sha256'),'hex'));
END $$;
CREATE FUNCTION reject_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit records are append-only'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON audit_logs FOR EACH STATEMENT EXECUTE FUNCTION reject_audit_mutation();
CREATE FUNCTION enforce_reply_room() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM noctis.messages a JOIN noctis.messages b ON b.id=NEW.parent_id WHERE a.id=NEW.message_id AND a.channel_id IS NOT DISTINCT FROM b.channel_id AND a.conversation_id IS NOT DISTINCT FROM b.conversation_id) THEN RAISE EXCEPTION 'Reply must belong to the same conversation'; END IF; RETURN NEW; END $$;
CREATE TRIGGER reply_room BEFORE INSERT OR UPDATE ON message_replies FOR EACH ROW EXECUTE FUNCTION enforce_reply_room();
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA noctis FROM PUBLIC;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA noctis TO noctis_api;
GRANT EXECUTE ON FUNCTION append_audit(text,text,text,text,jsonb) TO noctis_auth,noctis_worker;
GRANT EXECUTE ON FUNCTION has_permission(text,text,text),member(text,text),channel_permission(text,text,text),blocked(text,text),friends(text,text) TO noctis_worker;

GRANT SELECT(id,created_at,updated_at,deleted_at) ON users TO noctis_api;
GRANT SELECT,INSERT,UPDATE ON users,profiles,devices,sessions,oauth_accounts,oauth_states TO noctis_auth;
GRANT SELECT,INSERT,UPDATE,DELETE ON user_settings TO noctis_auth;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA noctis TO noctis_api;
REVOKE ALL ON users,sessions,devices,oauth_accounts,oauth_states,integration_credentials,rate_limits,jobs,webhook_deliveries FROM noctis_api;
GRANT SELECT(id,created_at,updated_at,deleted_at) ON users TO noctis_api;
REVOKE INSERT,UPDATE,DELETE ON audit_logs,permissions FROM noctis_api;
GRANT SELECT ON audit_logs,permissions TO noctis_api;
REVOKE UPDATE,DELETE ON xp_transactions,user_badges FROM noctis_api;
GRANT SELECT,INSERT,UPDATE,DELETE ON rate_limits TO noctis_auth;
GRANT SELECT,INSERT,UPDATE,DELETE ON integrations,integration_credentials,integration_items,webhooks,webhook_deliveries,jobs,presence,voice_participants TO noctis_worker;
GRANT SELECT ON users,sessions,channels,servers,server_members,profiles,server_bans TO noctis_worker;
GRANT INSERT ON messages,notifications TO noctis_worker;
GRANT SELECT,DELETE ON uploads TO noctis_worker;
GRANT SELECT ON message_attachments TO noctis_worker;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA noctis TO noctis_api,noctis_auth,noctis_worker;

-- Every application policy checks the live session as well as its object scope.
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON profiles FOR SELECT TO noctis_api USING(session_valid() AND can_profile(user_id));
CREATE POLICY profile_write ON profiles FOR UPDATE TO noctis_api USING(session_valid() AND user_id=current_user_id()) WITH CHECK(user_id=current_user_id());
CREATE POLICY profile_auth ON profiles TO noctis_auth USING(true) WITH CHECK(true);
CREATE POLICY profile_worker ON profiles FOR SELECT TO noctis_worker USING(true);
ALTER TABLE servers ENABLE ROW LEVEL SECURITY;
CREATE POLICY server_read ON servers FOR SELECT TO noctis_api USING(session_valid() AND deleted_at IS NULL AND (is_public OR member(id) OR owner_id=current_user_id()));
CREATE POLICY server_create ON servers FOR INSERT TO noctis_api WITH CHECK(session_valid() AND owner_id=current_user_id());
CREATE POLICY server_update ON servers FOR UPDATE TO noctis_api USING(session_valid() AND has_permission(id,'MANAGE_SERVER')) WITH CHECK(has_permission(id,'MANAGE_SERVER'));
ALTER TABLE server_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY membership_read ON server_members FOR SELECT TO noctis_api USING(session_valid() AND (member(server_id) OR user_id=current_user_id()));
CREATE POLICY membership_write ON server_members FOR INSERT TO noctis_api WITH CHECK(session_valid() AND (user_id=current_user_id() OR has_permission(server_id,'MANAGE_SERVER')));
CREATE POLICY membership_update ON server_members FOR UPDATE TO noctis_api USING(session_valid() AND user_id=current_user_id()) WITH CHECK(user_id=current_user_id());
CREATE POLICY membership_delete ON server_members FOR DELETE TO noctis_api USING(session_valid() AND (user_id=current_user_id() OR has_permission(server_id,'KICK_MEMBERS')));
ALTER TABLE channels ENABLE ROW LEVEL SECURITY;
CREATE POLICY channel_read ON channels FOR SELECT TO noctis_api USING(session_valid() AND channel_permission(id,'VIEW_CHANNEL'));
CREATE POLICY channel_create ON channels FOR INSERT TO noctis_api WITH CHECK(session_valid() AND has_permission(server_id,'MANAGE_CHANNELS'));
CREATE POLICY channel_update ON channels FOR UPDATE TO noctis_api USING(session_valid() AND has_permission(server_id,'MANAGE_CHANNELS')) WITH CHECK(has_permission(server_id,'MANAGE_CHANNELS'));
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY message_read ON messages FOR SELECT TO noctis_api USING(session_valid() AND (channel_permission(channel_id,'VIEW_CHANNEL') OR in_conversation(conversation_id)));
CREATE POLICY message_create ON messages FOR INSERT TO noctis_api WITH CHECK(session_valid() AND author_id=current_user_id() AND (channel_permission(channel_id,'SEND_MESSAGES') OR in_conversation(conversation_id)));
CREATE POLICY message_update ON messages FOR UPDATE TO noctis_api USING(session_valid() AND (author_id=current_user_id() OR channel_permission(channel_id,'MANAGE_MESSAGES')) AND can_message(id)) WITH CHECK(can_message(id));
ALTER TABLE direct_conversations ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversation_read ON direct_conversations FOR SELECT TO noctis_api USING(session_valid() AND (in_conversation(id) OR created_by=current_user_id()));
CREATE POLICY conversation_create ON direct_conversations FOR INSERT TO noctis_api WITH CHECK(session_valid() AND created_by=current_user_id());
ALTER TABLE direct_conversation_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY conversation_members_read ON direct_conversation_members FOR SELECT TO noctis_api USING(session_valid() AND (in_conversation(conversation_id) OR user_id=current_user_id()));
CREATE POLICY conversation_members_create ON direct_conversation_members FOR INSERT TO noctis_api WITH CHECK(session_valid() AND EXISTS(SELECT 1 FROM direct_conversations WHERE id=conversation_id AND created_by=current_user_id()));
CREATE POLICY conversation_members_update ON direct_conversation_members FOR UPDATE TO noctis_api USING(session_valid() AND user_id=current_user_id()) WITH CHECK(user_id=current_user_id());
ALTER TABLE uploads ENABLE ROW LEVEL SECURITY;
CREATE POLICY upload_read ON uploads FOR SELECT TO noctis_api USING(session_valid() AND can_upload(id));
CREATE POLICY upload_create ON uploads FOR INSERT TO noctis_api WITH CHECK(session_valid() AND owner_id=current_user_id() AND (purpose='avatar' OR channel_permission(channel_id,'ATTACH_FILES') OR in_conversation(conversation_id)));

DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['roles','channel_categories','missions','badges','events','server_bans','moderation_actions','invitations'] LOOP
  EXECUTE format('ALTER TABLE noctis.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY scoped_read ON noctis.%I FOR SELECT TO noctis_api USING(noctis.session_valid() AND noctis.member(server_id))',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['user_settings','notifications','integrations','user_badges','xp_transactions'] LOOP
  EXECUTE format('ALTER TABLE noctis.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY own_read ON noctis.%I FOR SELECT TO noctis_api USING(noctis.session_valid() AND user_id=noctis.current_user_id())',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['message_replies','message_reactions','message_mentions','message_attachments','pinned_messages'] LOOP
  EXECUTE format('ALTER TABLE noctis.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY message_scope ON noctis.%I FOR SELECT TO noctis_api USING(noctis.session_valid() AND noctis.can_message(message_id))',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['mission_objectives','mission_rewards','mission_members'] LOOP
  EXECUTE format('ALTER TABLE noctis.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY mission_scope ON noctis.%I FOR SELECT TO noctis_api USING(noctis.session_valid() AND EXISTS(SELECT 1 FROM noctis.missions m WHERE m.id=mission_id))',t);
 END LOOP;
END $$;
CREATE POLICY roles_write ON roles FOR ALL TO noctis_api USING(session_valid() AND has_permission(server_id,'MANAGE_ROLES')) WITH CHECK(session_valid() AND has_permission(server_id,'MANAGE_ROLES'));
CREATE POLICY categories_write ON channel_categories FOR ALL TO noctis_api USING(session_valid() AND has_permission(server_id,'MANAGE_CHANNELS')) WITH CHECK(session_valid() AND has_permission(server_id,'MANAGE_CHANNELS'));
CREATE POLICY missions_write ON missions FOR ALL TO noctis_api USING(session_valid() AND has_permission(server_id,'MANAGE_MISSIONS')) WITH CHECK(session_valid() AND has_permission(server_id,'MANAGE_MISSIONS'));
CREATE POLICY badges_write ON badges FOR INSERT TO noctis_api WITH CHECK(session_valid() AND has_permission(server_id,'MANAGE_MISSIONS'));
CREATE POLICY event_write ON events FOR ALL TO noctis_api USING(session_valid() AND has_permission(server_id,'MANAGE_EVENTS')) WITH CHECK(session_valid() AND has_permission(server_id,'MANAGE_EVENTS'));
CREATE POLICY bans_write ON server_bans FOR ALL TO noctis_api USING(session_valid() AND has_permission(server_id,'BAN_MEMBERS')) WITH CHECK(session_valid() AND has_permission(server_id,'BAN_MEMBERS'));
CREATE POLICY moderation_write ON moderation_actions FOR INSERT TO noctis_api WITH CHECK(session_valid() AND actor_id=current_user_id() AND member(server_id));
CREATE POLICY invite_write ON invitations FOR ALL TO noctis_api USING(session_valid() AND has_permission(server_id,'CREATE_INVITE')) WITH CHECK(session_valid() AND has_permission(server_id,'CREATE_INVITE'));
CREATE POLICY settings_write ON user_settings FOR ALL TO noctis_api USING(session_valid() AND user_id=current_user_id()) WITH CHECK(session_valid() AND user_id=current_user_id());
CREATE POLICY settings_auth ON user_settings TO noctis_auth USING(true) WITH CHECK(true);
CREATE POLICY notification_update ON notifications FOR UPDATE TO noctis_api USING(session_valid() AND user_id=current_user_id()) WITH CHECK(user_id=current_user_id());
CREATE POLICY notification_create ON notifications FOR INSERT TO noctis_api WITH CHECK(session_valid() AND actor_id=current_user_id());
CREATE POLICY integration_delete ON integrations FOR DELETE TO noctis_api USING(session_valid() AND user_id=current_user_id());
CREATE POLICY xp_read_server ON xp_transactions FOR SELECT TO noctis_api USING(session_valid() AND member(server_id));
CREATE POLICY xp_claim ON xp_transactions FOR INSERT TO noctis_api WITH CHECK(session_valid() AND user_id=current_user_id() AND member(server_id) AND reward_id IS NOT NULL);
CREATE POLICY badge_claim ON user_badges FOR INSERT TO noctis_api WITH CHECK(session_valid() AND user_id=current_user_id());
CREATE POLICY replies_create ON message_replies FOR INSERT TO noctis_api WITH CHECK(session_valid() AND can_message(parent_id) AND EXISTS(SELECT 1 FROM messages m WHERE m.id=message_id AND m.author_id=current_user_id()));
CREATE POLICY reaction_create ON message_reactions FOR INSERT TO noctis_api WITH CHECK(session_valid() AND user_id=current_user_id() AND can_message(message_id));
CREATE POLICY reaction_delete ON message_reactions FOR DELETE TO noctis_api USING(session_valid() AND user_id=current_user_id() AND can_message(message_id));
CREATE POLICY mention_create ON message_mentions FOR INSERT TO noctis_api WITH CHECK(session_valid() AND EXISTS(SELECT 1 FROM messages m WHERE m.id=message_id AND m.author_id=current_user_id()));
CREATE POLICY attachment_create ON message_attachments FOR INSERT TO noctis_api WITH CHECK(session_valid() AND EXISTS(SELECT 1 FROM messages m WHERE m.id=message_id AND m.author_id=current_user_id()) AND EXISTS(SELECT 1 FROM uploads u WHERE u.id=upload_id AND u.owner_id=current_user_id()));
CREATE POLICY pin_write ON pinned_messages FOR ALL TO noctis_api USING(session_valid() AND EXISTS(SELECT 1 FROM messages m WHERE m.id=message_id AND (channel_permission(m.channel_id,'MANAGE_MESSAGES') OR in_conversation(m.conversation_id)))) WITH CHECK(session_valid() AND pinned_by=current_user_id() AND EXISTS(SELECT 1 FROM messages m WHERE m.id=message_id AND (channel_permission(m.channel_id,'MANAGE_MESSAGES') OR in_conversation(m.conversation_id))));
CREATE POLICY objectives_write ON mission_objectives FOR ALL TO noctis_api USING(session_valid() AND EXISTS(SELECT 1 FROM missions m WHERE m.id=mission_id AND has_permission(m.server_id,'MANAGE_MISSIONS'))) WITH CHECK(session_valid() AND EXISTS(SELECT 1 FROM missions m WHERE m.id=mission_id AND has_permission(m.server_id,'MANAGE_MISSIONS')));
CREATE POLICY rewards_write ON mission_rewards FOR INSERT TO noctis_api WITH CHECK(session_valid() AND EXISTS(SELECT 1 FROM missions m WHERE m.id=mission_id AND has_permission(m.server_id,'MANAGE_MISSIONS')));
CREATE POLICY mission_join ON mission_members FOR INSERT TO noctis_api WITH CHECK(session_valid() AND user_id=current_user_id() AND EXISTS(SELECT 1 FROM missions m WHERE m.id=mission_id));
ALTER TABLE mission_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY progress_read ON mission_progress FOR SELECT TO noctis_api USING(session_valid() AND (user_id=current_user_id() OR EXISTS(SELECT 1 FROM mission_objectives o JOIN missions m ON m.id=o.mission_id WHERE o.id=objective_id AND has_permission(m.server_id,'MANAGE_MISSIONS'))));
CREATE POLICY progress_write ON mission_progress FOR ALL TO noctis_api USING(session_valid() AND user_id=current_user_id()) WITH CHECK(session_valid() AND (user_id=current_user_id() OR EXISTS(SELECT 1 FROM mission_objectives o JOIN missions m ON m.id=o.mission_id WHERE o.id=objective_id AND has_permission(m.server_id,'MANAGE_MISSIONS'))));
ALTER TABLE event_participants ENABLE ROW LEVEL SECURITY;
CREATE POLICY participant_read ON event_participants FOR SELECT TO noctis_api USING(session_valid() AND EXISTS(SELECT 1 FROM events WHERE id=event_id));
CREATE POLICY participant_write ON event_participants FOR ALL TO noctis_api USING(session_valid() AND user_id=current_user_id() AND EXISTS(SELECT 1 FROM events WHERE id=event_id)) WITH CHECK(session_valid() AND user_id=current_user_id() AND EXISTS(SELECT 1 FROM events WHERE id=event_id));
ALTER TABLE role_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_permission_read ON role_permissions FOR SELECT TO noctis_api USING(session_valid() AND EXISTS(SELECT 1 FROM roles WHERE id=role_id));
CREATE POLICY role_permission_write ON role_permissions FOR ALL TO noctis_api USING(session_valid() AND EXISTS(SELECT 1 FROM roles WHERE id=role_id AND has_permission(server_id,'MANAGE_ROLES'))) WITH CHECK(session_valid() AND EXISTS(SELECT 1 FROM roles WHERE id=role_id AND has_permission(server_id,'MANAGE_ROLES')));
ALTER TABLE member_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY member_role_read ON member_roles FOR SELECT TO noctis_api USING(session_valid() AND member(server_id));
CREATE POLICY member_role_write ON member_roles FOR ALL TO noctis_api USING(session_valid() AND has_permission(server_id,'MANAGE_ROLES')) WITH CHECK(session_valid() AND has_permission(server_id,'MANAGE_ROLES'));
ALTER TABLE channel_role_permissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY override_read ON channel_role_permissions FOR SELECT TO noctis_api USING(session_valid() AND channel_permission(channel_id,'VIEW_CHANNEL'));
CREATE POLICY override_write ON channel_role_permissions FOR ALL TO noctis_api USING(session_valid() AND EXISTS(SELECT 1 FROM channels WHERE id=channel_id AND has_permission(server_id,'MANAGE_ROLES'))) WITH CHECK(session_valid() AND EXISTS(SELECT 1 FROM channels WHERE id=channel_id AND has_permission(server_id,'MANAGE_ROLES')));
ALTER TABLE channel_reads ENABLE ROW LEVEL SECURITY;
CREATE POLICY reads_own ON channel_reads TO noctis_api USING(session_valid() AND user_id=current_user_id()) WITH CHECK(session_valid() AND user_id=current_user_id() AND channel_permission(channel_id,'VIEW_CHANNEL'));
ALTER TABLE friendships ENABLE ROW LEVEL SECURITY;
CREATE POLICY friends_read ON friendships FOR SELECT TO noctis_api USING(session_valid() AND current_user_id() IN(requester_id,recipient_id));
CREATE POLICY friends_create ON friendships FOR INSERT TO noctis_api WITH CHECK(session_valid() AND requester_id=current_user_id() AND NOT blocked(requester_id,recipient_id));
CREATE POLICY friends_update ON friendships FOR UPDATE TO noctis_api USING(session_valid() AND recipient_id=current_user_id()) WITH CHECK(recipient_id=current_user_id());
CREATE POLICY friends_delete ON friendships FOR DELETE TO noctis_api USING(session_valid() AND current_user_id() IN(requester_id,recipient_id));
ALTER TABLE user_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY blocks_own ON user_blocks TO noctis_api USING(session_valid() AND blocker_id=current_user_id()) WITH CHECK(session_valid() AND blocker_id=current_user_id());
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_read ON audit_logs FOR SELECT TO noctis_api USING(session_valid() AND has_permission(server_id,'VIEW_AUDIT_LOG'));
ALTER TABLE integration_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY integration_items_read ON integration_items FOR SELECT TO noctis_api USING(session_valid() AND EXISTS(SELECT 1 FROM integrations WHERE id=integration_id));
ALTER TABLE webhooks ENABLE ROW LEVEL SECURITY;
CREATE POLICY webhook_scope ON webhooks TO noctis_api USING(session_valid() AND has_permission(server_id,'MANAGE_SERVER')) WITH CHECK(session_valid() AND has_permission(server_id,'MANAGE_SERVER'));
ALTER TABLE voice_participants ENABLE ROW LEVEL SECURITY;
CREATE POLICY voice_read ON voice_participants FOR SELECT TO noctis_api USING(session_valid() AND channel_permission(channel_id,'VIEW_CHANNEL'));
CREATE POLICY voice_self ON voice_participants TO noctis_api USING(session_valid() AND user_id=current_user_id() AND channel_permission(channel_id,'CONNECT_VOICE')) WITH CHECK(session_valid() AND user_id=current_user_id() AND channel_permission(channel_id,'CONNECT_VOICE'));
CREATE POLICY voice_moderator ON voice_participants FOR UPDATE TO noctis_api USING(session_valid() AND EXISTS(SELECT 1 FROM channels c WHERE c.id=channel_id AND (has_permission(c.server_id,'MUTE_MEMBERS') OR has_permission(c.server_id,'DEAFEN_MEMBERS') OR has_permission(c.server_id,'MOVE_MEMBERS')))) WITH CHECK(session_valid() AND channel_permission(channel_id,'VIEW_CHANNEL'));
ALTER TABLE presence ENABLE ROW LEVEL SECURITY;
CREATE POLICY presence_read ON presence FOR SELECT TO noctis_api USING(session_valid() AND can_profile(user_id));
CREATE POLICY presence_self ON presence TO noctis_api USING(session_valid() AND user_id=current_user_id()) WITH CHECK(session_valid() AND user_id=current_user_id());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['servers','server_members','channels','profiles','server_bans','messages','notifications','uploads','message_attachments','integrations','integration_items','webhooks','voice_participants','presence'] LOOP EXECUTE format('CREATE POLICY worker_service ON noctis.%I TO noctis_worker USING(true) WITH CHECK(true)',t); END LOOP; END $$;
RESET search_path;
